import{_ as a,o,c as s,ae as r}from"./chunks/framework.EHGTsUvI.js";const u=JSON.parse('{"title":"Crop Silos","description":"","frontmatter":{"title":"Crop Silos"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/shirt.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/shirt.md"}'),t={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/shirt.md"};function i(n,e,l,p,d,c){return o(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="crop-silos" tabindex="-1">Crop Silos <a class="header-anchor" href="#crop-silos" aria-label="Permalink to &quot;Crop Silos&quot;">​</a></h1><p>Crop Silos are storage buildings used to store harvested crops. They allow players to store large quantities of crops without needing to keep them inside trailers or other vehicles.</p><p>Crop Silos are particularly useful for large-scale farming and production chains where crops need to be stored before being transported to factories.</p><h2 id="building-information" tabindex="-1">Building Information <a class="header-anchor" href="#building-information" aria-label="Permalink to &quot;Building Information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Building</td><td>Crop Silo</td></tr><tr><td>Purpose</td><td>Crop Storage</td></tr><tr><td>Capacity</td><td>300 Crop Boxes</td></tr><tr><td>Storage Type</td><td>Crops</td></tr><tr><td>Build Menu</td><td>Create &gt; Buildings</td></tr></tbody></table><p>Each Crop Silo can hold up to <strong>300 boxes of crops</strong>.</p><h2 id="stored-crops" tabindex="-1">Stored Crops <a class="header-anchor" href="#stored-crops" aria-label="Permalink to &quot;Stored Crops&quot;">​</a></h2><p>Crop Silos can be used to store harvested crops such as:</p><ul><li>Wheat</li><li>Corn</li><li>Rice</li><li>Oats</li><li>Other compatible harvested crops</li></ul><p>The silo is designed for storing loose/boxed crop products rather than finished factory products.</p><h2 id="how-to-use-a-crop-silo" tabindex="-1">How to Use a Crop Silo <a class="header-anchor" href="#how-to-use-a-crop-silo" aria-label="Permalink to &quot;How to Use a Crop Silo&quot;">​</a></h2><h3 id="_1-purchase-the-silo" tabindex="-1">1. Purchase the Silo <a class="header-anchor" href="#_1-purchase-the-silo" aria-label="Permalink to &quot;1. Purchase the Silo&quot;">​</a></h3><p>Open the <strong>Create</strong> menu and purchase a Crop Silo.</p><p>Place the silo somewhere accessible to your farming equipment and transport vehicles.</p><h3 id="_2-load-crops" tabindex="-1">2. Load Crops <a class="header-anchor" href="#_2-load-crops" aria-label="Permalink to &quot;2. Load Crops&quot;">​</a></h3><p>Bring your harvested crops to the Crop Silo using a suitable vehicle or trailer.</p><p>Unload the crops into the silo&#39;s storage area.</p><p>The crops will be added to the silo&#39;s available storage.</p><h3 id="_3-store-crops" tabindex="-1">3. Store Crops <a class="header-anchor" href="#_3-store-crops" aria-label="Permalink to &quot;3. Store Crops&quot;">​</a></h3><p>Once the crops have been deposited, they remain stored inside the silo.</p><p>The silo can hold up to <strong>300 boxes of crops</strong>.</p><h3 id="_4-remove-crops" tabindex="-1">4. Remove Crops <a class="header-anchor" href="#_4-remove-crops" aria-label="Permalink to &quot;4. Remove Crops&quot;">​</a></h3><p>When you need the crops for selling or production, use a suitable vehicle or trailer at the silo&#39;s loading area.</p><p>The stored crops can then be transferred into the vehicle for transportation.</p><h2 id="crop-storage-chain" tabindex="-1">Crop Storage Chain <a class="header-anchor" href="#crop-storage-chain" aria-label="Permalink to &quot;Crop Storage Chain&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Crop Field</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Harvest</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Crop Boxes</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Crop Silo</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>┌───────────────┐</span></span>
<span class="line"><span>│               │</span></span>
<span class="line"><span>Factory       Sell</span></span>
<span class="line"><span>│               │</span></span>
<span class="line"><span>Production   Sell Point</span></span></code></pre></div><h2 id="uses" tabindex="-1">Uses <a class="header-anchor" href="#uses" aria-label="Permalink to &quot;Uses&quot;">​</a></h2><p>Crop Silos are especially useful for:</p><ul><li>Storing crops between harvests</li><li>Building up large quantities of ingredients</li><li>Supplying production factories</li><li>Reducing the need for multiple trailers</li><li>Preparing crops for large production batches</li></ul><blockquote><p><strong>Tip:</strong> Crop Silos are particularly useful when running factories such as the <strong>Animal Food Factory</strong>, <strong>Cake Factory</strong>, and <strong>Honey Oatmeal Factory</strong>, where large quantities of harvested crops may be required.</p></blockquote>`,30)])])}const g=a(t,[["render",i]]);export{u as __pageData,g as default};
